{
  "steps": [
    {
      "task": "get_columns_with_first_row",
      "player": "dataset_schema_preview",
      "rationale": "Preview the dataset schema and capture the first row values for all columns to establish the structural baseline.",
      "target_resources": [],
      "inputs": {},
      "outputs": ["schema_preview"]
    },
    {
      "task": "get_field_statistics",
      "player": "data_analyst",
      "rationale": "Profile each field to obtain statistical summaries (counts, types, missing values) needed for later metadata synthesis.",
      "target_resources": [],
      "inputs": {
        "schema_preview": "schema_preview"
      },
      "outputs": ["field_statistics"]
    },
    {
      "task": "detect_temporal_columns; detect_spatial_columns; get_temporal_extent; get_spatial_extent",
      "player": "spatial_temporal_specialist",
      "rationale": "Identify temporal and spatial columns, then compute their extents to provide spatialCoverage, temporalCoverage, and resolution information.",
      "target_resources": [],
      "inputs": {
        "schema_preview": "schema_preview"
      },
      "outputs": ["spatial_temporal_data"]
    },
    {
      "task": "generate_metadata",
      "player": "metadata_generator",
      "rationale": "Combine schema preview, field statistics, and spatial‑temporal analysis with the active standard to produce the final seven‑field metadata record.",
      "target_resources": [],
      "inputs": {
        "metadata_standard": "pangaea_descriptive_technical_standard",
        "schema": "schema_preview",
        "statistics": "field_statistics",
        "spatial_temporal": "spatial_temporal_data"
      },
      "outputs": ["metadata_output"]
    }
  ]
}
